/**
 * Tra icon nội tuyến theo TÊN — dùng làm FALLBACK cho MenuManager.
 *
 * Bối cảnh: `MenuManager/menuIconCatalog.ts` nay chỉ còn DANH SÁCH TINH TUYỂN (named import thay
 * cho `Object.keys`, xem giải thích trong file đó). Menu đã lưu trong DB có thể trỏ tới tên icon
 * không còn trong danh mục ⇒ nếu không fallback thì menu cũ sẽ mất icon. Bộ icon nội tuyến này
 * chính là các icon sidebar đang dùng (đọc từ menu CMS/PVN/NHATHAN) nên phủ được phần lớn.
 */
const iconByNameCache: Record<string, React.ComponentType<any>> = {};
export const hasLocalIcon = (name?: string): boolean => !!name && !!ICON_DATA[name];
export const getLocalIcon = (name?: string): React.ComponentType<any> | undefined => {
  if (!name || !ICON_DATA[name]) return undefined;
  if (!iconByNameCache[name]) iconByNameCache[name] = genIcon(ICON_DATA[name]);
  return iconByNameCache[name];
};

export const LOCAL_ICONS = ICON_DATA;
